const results = $input.first().json.results || [];
const count = $('Set Config').first().json.top_results_count || 5;

if (results.length === 0) {
  throw new Error('Brave Search returned no results. Verify the API key and search query in Set Config.');
}

const topN = results.slice(0, count).map((item, i) => ({
  index: i + 1,
  title: item.title || 'No title',
  description: item.description || 'No description available.',
  url: item.url || '',
  source: item.meta_url?.hostname || 'unknown',
  published: item.age || 'unknown'
}));

const formatted = topN.map(a =>
  `${a.index}. ${a.title}\nDescription: ${a.description}\nSource: ${a.source} | Published: ${a.published}\nURL: ${a.url}`
).join('\n\n');

return [{ json: { articles_raw: topN, articles_formatted: formatted } }];

