// Parse the raw JSON string output from Idea and Plan Agent
function fixCommonIssues(str) {
  if (typeof str !== 'string') return str;
  str = str.trim();
  // Strip surrounding quotes
  if ((str.startsWith('"') && str.endsWith('"')) || (str.startsWith("'") && str.endsWith("'"))) {
    str = str.slice(1, -1);
  }
  // Normalize smart quotes
  str = str.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");
  // Strip markdown fences
  str = str.replace(/^```[a-z]*\n?/i, '').replace(/```$/i, '').trim();
  // Remove trailing commas before } or ]
  str = str.replace(/,\s*([}\]])/g, '$1');
  // Remove control characters
  str = str.replace(/[\u0000-\u001F]+/g, ' ');
  return str;
}

function tryParseJson(str) {
  try {
    return JSON.parse(str);
  } catch {
    const fixed = fixCommonIssues(str);
    try {
      return JSON.parse(fixed);
    } catch {
      const first = fixed.indexOf('{');
      const last = fixed.lastIndexOf('}');
      if (first !== -1 && last !== -1 && last > first) {
        return JSON.parse(fixed.slice(first, last + 1));
      }
      throw new Error('Failed to parse JSON from Idea and Plan Agent output.');
    }
  }
}

const rawText = $input.first().json.output;
let parsed = null;
let error = null;

try {
  parsed = tryParseJson(rawText);
} catch (e) {
  error = e.message;
}

if (error || !parsed) {
  throw new Error(`Create JSON failed: ${error}. Raw output: ${rawText?.slice(0, 500)}`);
}

// Ensure image_prompts is always an array
if (!Array.isArray(parsed.image_prompts)) {
  parsed.image_prompts = [];
}

return [{ json: { parsed, error: null } }];

// Retrieve all input items
const items = $input.all();

const results = items.map(item => {
  const raw = item.json.full_article || '';

  // Preserve HTML structure — only collapse excessive whitespace between tags
  // Do NOT strip newlines blindly as they may be part of HTML formatting
  const cleanedText = raw
    .replace(/\t/g, ' ')           // Replace tabs with spaces
    .replace(/\n{3,}/g, '\n\n')    // Max 2 consecutive newlines
    .replace(/[ ]{2,}/g, ' ')      // Collapse multiple spaces into one
    .trim();

  if (!cleanedText) {
    throw new Error('Cleaned article is empty. Check Code in JavaScript1 output.');
  }

  return { json: { cleanedText } };
});

return results;

// Retrieve all aggregated article parts
const parts = $json.article_part;

if (!parts || !Array.isArray(parts)) {
  throw new Error('article_part is missing or not an array. Check Aggregate2 output.');
}

// Combine all section HTML fragments into one full article
const fullArticle = parts
  .map(part => part.text || part.output || '')
  .filter(text => text.trim().length > 0)
  .join('\n\n');

if (!fullArticle.trim()) {
  throw new Error('Full article is empty. All parts returned no text.');
}

return [{ json: { full_article: fullArticle } }];

// This Code node splits a long text into sections based on "Part X Title:"
// and creates structured JSON: { plan: { part_1: "...", part_2: "...", ... } }

const input = $input.item.json.output || '';

if (typeof input !== 'string' || !input.trim()) {
  throw new Error("Input text is empty or invalid. Please make sure 'output' contains plain text.");
}

// Split text by "Part <number> Title:"
const parts = input
  .split(/(?=Part\s+\d+\s+Title:)/g) // keep 'Part X Title:' at the start of each section
  .map(p => p.trim())
  .filter(p => p.length > 0);

// Build structured JSON
const plan = {};

parts.forEach((part, index) => {
  // Optional: extract title for readability
  const match = part.match(/Part\s+(\d+)\s+Title:\s*(.*?)(?:\n|\\n)/);
  const title = match ? match[2].trim() : `Part ${index + 1}`;
  plan[`part_${index + 1}`] = {
    title,
    content: part
  };
});

// Return structured result
return [
  {
    json: { plan }
  }
];

