const raw = $input.first().json.text;

// Fix common LLM formatting issues
function fixAndParse(str) {
  if (typeof str !== 'string') {
    // Already an object — try to use directly
    if (str && str.selected_articles) return str;
    throw new Error('Input is not a string or valid object.');
  }

  str = str.trim();

  // Strip markdown fences
  str = str.replace(/^```[a-z]*\n?/i, '').replace(/```$/i, '').trim();

  // Normalize smart quotes
  str = str.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");

  // Remove trailing commas before } or ]
  str = str.replace(/,\s*([}\]])/g, '$1');

  // Remove control characters except newline/tab
  str = str.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]+/g, ' ');

  // Try parsing
  try {
    return JSON.parse(str);
  } catch {
    // Try extracting JSON object between first { and last }
    const first = str.indexOf('{');
    const last = str.lastIndexOf('}');
    if (first !== -1 && last !== -1 && last > first) {
      return JSON.parse(str.slice(first, last + 1));
    }
    throw new Error('Failed to parse JSON. Raw input: ' + str.slice(0, 300));
  }
}

const parsed = fixAndParse(raw);

if (!parsed.selected_articles || !Array.isArray(parsed.selected_articles)) {
  throw new Error('selected_articles array not found in parsed output.');
}

// Return one item per article — ready for Loop Over Items
return parsed.selected_articles.map(article => ({
  json: {
    rank: article.rank,
    title: article.title,
    topic: article.topic,
    description: article.description,
    source_url: article.source_url,
    source_title: article.source_title,
    primary_keyword: article.primary_keyword,
    keywords: article.keywords,
    language: article.language
  }
}));

